-- Periodos de Shabat y Yom Tov (Ciudad de México): durante estos periodos las respuestas a preguntas
-- de Mercado Libre se publican automáticamente, sin visto bueno.
-- inicio = 30 min antes de la puesta de sol de la víspera; fin = 50 min después de la puesta de sol del último día.
-- Calculado con pyluach (Yom Tov de la diáspora) + astral (19.4326, -99.1332).
create table if not exists public.shabat_periodos (
  inicio  timestamptz primary key,
  fin     timestamptz not null,
  motivo  text not null
);
alter table public.shabat_periodos enable row level security;

on conflict (inicio) do nothing;
